_CACHE = {}

def get_asset(name: str) -> bytes | None:
    norm = name.replace("\\", "/").strip("/")
    if norm in _CACHE:
        return _CACHE[norm]
    comp = _ASSETS.get(norm)
    if comp is None:
        return None
    data = zlib.decompress(comp)
    _CACHE[norm] = data
    return data

def get_asset_stream(name: str) -> io.BytesIO | None:
    data = get_asset(name)
    if data is None:
        return None
    return io.BytesIO(data)

def get_asset_text(name: str, encoding: str = "utf-8") -> str | None:
    data = get_asset(name)
    if data is None:
        return None
    return data.decode(encoding, errors="ignore")
